package com.ecotrack.backend.gamification; import com.ecotrack.backend.user.User; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="user_badges") public class UserBadge{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id")User user;@ManyToOne(fetch=FetchType.EAGER)@JoinColumn(name="badge_id")Badge badge;Instant earnedAt=Instant.now();public Badge getBadge(){return badge;}public Instant getEarnedAt(){return earnedAt;}}
